import { test, expect } from '@playwright/test';

test.describe('In-app Notifications Real-time Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display new notification in real-time without page refresh', async ({ page }) => {
    // Wait for notifications container to be visible
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    // Get initial notification count
    const initialNotifications = await page.getByRole('listitem').filter({ hasText: /notification/i }).count();

    // Trigger a new notification (e.g., by clicking a button that generates one)
    const triggerButton = page.getByRole('button', { name: /send notification/i });
    await triggerButton.click();

    // Wait for new notification to appear without refresh
    const newNotification = page.getByRole('listitem').filter({ hasText: /new notification/i }).first();
    await expect(newNotification).toBeVisible({ timeout: 5000 });

    // Verify notification count increased
    const updatedNotifications = await page.getByRole('listitem').filter({ hasText: /notification/i }).count();
    expect(updatedNotifications).toBeGreaterThan(initialNotifications);
  });

  test('should update notification status in real-time', async ({ page }) => {
    // Wait for notifications to load
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    // Find an unread notification
    const unreadNotification = page.getByRole('listitem').filter({ hasText: /unread/i }).first();
    await expect(unreadNotification).toBeVisible();

    // Mark notification as read by clicking on it
    await unreadNotification.click();

    // Verify the notification status updates in real-time without refresh
    const readNotification = page.getByRole('listitem').filter({ hasText: /read/i }).first();
    await expect(readNotification).toBeVisible({ timeout: 5000 });

    // Verify unread badge is removed or updated
    const unreadBadge = unreadNotification.getByText(/unread/i);
    await expect(unreadBadge).not.toBeVisible({ timeout: 5000 });
  });

  test('should handle multiple notifications arriving simultaneously', async ({ page }) => {
    // Wait for notifications container
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    // Get initial notification count
    const initialCount = await page.getByRole('listitem').filter({ hasText: /notification/i }).count();

    // Trigger multiple notifications at once
    const bulkSendButton = page.getByRole('button', { name: /send multiple/i });
    await bulkSendButton.click();

    // Wait for all notifications to appear
    await page.waitForTimeout(2000);

    // Verify all notifications are displayed without refresh
    const finalCount = await page.getByRole('listitem').filter({ hasText: /notification/i }).count();
    expect(finalCount).toBeGreaterThan(initialCount);

    // Verify each notification is visible
    const allNotifications = page.getByRole('listitem').filter({ hasText: /notification/i });
    const count = await allNotifications.count();
    for (let i = 0; i < count; i++) {
      await expect(allNotifications.nth(i)).toBeVisible();
    }
  });

  test('should dismiss notification in real-time', async ({ page }) => {
    // Wait for notifications container
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    // Get a notification and its close button
    const notification = page.getByRole('listitem').filter({ hasText: /notification/i }).first();
    await expect(notification).toBeVisible();

    // Click close/dismiss button
    const closeButton = notification.getByRole('button', { name: /close|dismiss|×/i });
    await closeButton.click();

    // Verify notification is removed in real-time without refresh
    await expect(notification).not.toBeVisible({ timeout: 5000 });
  });
});
